"""One idea: market microstructure close-location pressure residualized from RAV momentum."""
exec(open('scripts/miner_3_20270128_close_location_pressure_20.py').read().replace("F=loc.rolling(20,min_periods=15).mean()-loc.rolling(60,min_periods=40).mean()", "F0=loc.rolling(20,min_periods=15).mean()-loc.rolling(60,min_periods=40).mean()\n# remove contemporaneous canonical risk-adjusted momentum cross-sectionally\nprevol=R.rolling(20,min_periods=15).std(); prebase=(P/P.shift(20)-1)/prevol\nF=pd.DataFrame(index=P.index,columns=A,dtype=float)\nfor dt in P.index:\n z=pd.concat([F0.loc[dt].rename('x'),prebase.loc[dt].rename('m')],axis=1).dropna()\n if len(z)>=8 and z.m.var()>0:\n  b=np.cov(z.x,z.m,ddof=1)[0,1]/z.m.var(); F.loc[dt,z.index]=z.x-(z.x.mean()-b*z.m.mean()+b*z.m)").replace("FACTOR close_location_pressure_surprise_20", "FACTOR rav_residual_close_location_pressure_20").replace("expression=mean20((close-low)/(high-low))-mean60((close-low)/(high-low))", "expression=residual_cs[mean20(close_location)-mean60(close_location) ~ return20/vol20]"))
